INSERT INTO `programs` (`id`, `external_id`, `school_id`, `name`, `program_type`, `teaching_language`, `tags`, `introduction`, `duration`, `duration_note`, `major_text`, `direction_text`, `requirements_text`, `semester_text`, `application_time_text`, `scholarship_category`, `scholarship_content`, `scholarship_note`, `scholarship_deadline_text`, `accommodation_text`, `insurance_text`, `application_fee_text`, `scholarship_application_fee_text`, `fee_note`, `tuition_text`, `tuition_min`, `tuition_max`, `tuition_period`, `accommodation_min`, `accommodation_max`, `insurance_max`, `application_fee_max`, `first_year_cost_max`, `cost_incomplete`, `csca_status`, `hsk_level_min`, `hsk_score_min`, `ielts_min`, `toefl_min`, `duolingo_min`, `gpa_min`, `gpa_scale`, `min_age`, `max_age`, `deadline_date`, `deadline_status`, `parsed_json`, `raw_json`, `source_batch_id`, `review_status`, `manually_verified`, `archived`, `created_at`, `updated_at`) VALUES
('b08a069e-7357-43bd-9ca0-4e940af73ea5', NULL, 'e2a39eb1-9d45-43db-9fd1-7c714b250101', '深圳大学 · 本科 · 中文授课', 'UG', 'CHINESE', NULL, '深圳大学开设多门本科专业面向国际学生招生，覆盖文科、理科、医学、艺术等多个领域，专业选择丰富。学校依托大湾区区位优势，注重留学生培养管理与文化实践活动，拓展实习就业渠道，为国际学生提供优质的留学与发展平台。', '4年', NULL, '汉语言文学\n汉语国际教育\n网络与新媒体\n英语\n日语\n金融科技\n心理学\n学前教育\n美术学\n设计学类\n表演（影视戏剧）\n音乐表演(声乐演唱)\n音乐表演(器乐演奏)\n音乐表演(音乐编创)\n音乐表演(流行演唱)\n舞蹈编导\n播音与主持艺术\n电子信息工程\n电子科学与技术\n计算机类\n智慧交通\n工程管理\n智能建造\n土木工程（国际工程创新班)\n土木工程（数学力学创新班）\n高分子材料与工程\n材料科学与工程\n化学\n环境工程\n新能源科学与工程\n食品科学与工程\n法学\n行政管理\n社会学\n工商管理\n电子商务\n人力资源管理\n市场营销\n信息管理与信息系统', '汉语言文学专业大三分专业方向（商务、中文+AI）；\n美术学专业大三分专业方向（国画、油画、版画、雕塑）；\n设计学类大二分专业【艺术设计学（创意策划与设计管理）、视觉传达设计、环境设计、产品设计、服装与服饰设计、数字媒体艺术】。', '申请条件\n（一）申请人须是非中国国籍公民，年满18周岁且不超过25周岁，持有效外国护照，身体健康，品行端正，遵守中国法律、法规和学校的规章制度。\n（二）高中毕业及以上学历（申请时尚未毕业须提供预毕业证明，最迟在入学前取得高中毕业证书）。\n（三）满足相应的语言水平要求（证书须在有效期内） 。\n1、中文授课专业：\n①理工科专业：HSK4级180分以上\n②文科、医学、艺术专业：HSK5级180分以上\n③汉语言文学、汉语国际教育本科：无HSK要求\n*母语为汉语者经我校认定可免交相应语言水平证明。\n（四）符合教育部教外函【2020】12号文件规定。\n中华人民共和国教育部《教外函〔2020〕12号》。“一、依据《中华人民共和国国籍法》第五条，父母双方或一方为中国公民并定居在外国，本人出生时即具有外国国籍的，不具有中国国籍。自2021年起，其申请作为国际学生进入我高等学校本专科阶段学习，除符合学校的其他报名资格外，还应持有有效的外国护照或国籍证明文件4年（含）以上，且最近4年（截至入学年度的4月30日前）之内有在外国实际居住2年以上的记录（一年中实际在外国居住满9个月可按一年计算，以入境和出境签章为准）。二、祖国大陆（内地）、香港、澳门和台湾居民在移民并获得外国国籍后申请作为国际学生进入我高等学校本专科阶段学习的，应满足本通知第一项要求。”\n\n申请材料\n（一）高中毕业证书、成绩单原件扫描件，应届生可提供就读高中出具的预毕业证明。（入学前必须取得毕业证书，入学时将查验）\n（二）护照个人信息页\n（三）护照照片\n（四）语言水平证明 （证书须在有效期内）\n中文授课专业（汉语言文学和汉语国际教育专业除外）：\n①理工科专业：HSK4级证书（180分以上）\n②文科、医学、艺术专业：HSK5级证书（180分以上）\n（五）外国人体检报告\n（六）个人履历（从小学至今）\n（七）两封学校或任课老师推荐信（推荐人签字并注明电子邮箱和联系电话）和来华学习计划 (500字左右）。', '9月开学，每年两个学期', '1月1日-3月20日（第一批）；\n3月20日-5月31日（第二批）', '广东省政府来粤留学生奖学金\n深圳大运奖学金\n荔园奖学金\n国际中文教师奖学金', '广东省政府来粤留学生奖学金，10000元/年\n深圳大运奖学金，30000元/年\n荔园奖学金：\n一等，免学费，并提供 12000 元/年生活补助，按月发放\n二等，免学费\n三等，免学费的 50%\n国际中文教师奖学金：学费、住宿费、生活费和综合医疗保险费', '广东省政府来粤留学生奖学金：1.申请人须拥有外国国籍，持有有效外国护照，身体健康，对华友好。\n2.申请来粤接受本科阶段学历教育的，须获得本人所在国高级中学（含）以上毕业证，年龄在30周岁以下；\n3.申请人学业成绩优异，来粤学习目的明确，并根据拟就读大学的专业设置，并结合自身兴趣和专业特长，制订了清晰的学习计划。\n4.申请人必须已被我校录取。\n5.申请人必须是没有享受中国政府各类奖学金、孔子学院奖学金及其他任何中国各级政府资助形式。\n\n深圳大运奖学金：本科生最近两个学期每学期绩点不低于3.5且无必修不及格\n\n国际中文教师奖学金：具有高中学历，且中文水平考试成绩达到HSK（四级）210分、HSKK（中级）60分。', '广东省政府来粤留学生奖学金、荔园奖学金：截止日期：5月31日\n深圳大运奖学金：入学第二年开始申请（具体时间根据学院通知）\n国际中文教师奖学金：2026年2月20日至2026年5月15日', '粤海校区宿舍设有单人间和双人间可供选择，费用为2400-8000元/学期；\n丽湖校区宿舍为四人间，费用为750元/学期。\n学生需按房型自行缴纳住宿费（水电费另外计收）。当前校内住宿紧张，有可能安排在校外住宿，具体费用另行通知。', '400元/学期', '400元', NULL, NULL, '文科：26000元/年\n理科：30000元/年\n医学、艺术、体育类： 40000元/年', 26000, 40000, 'YEAR', 750, 8000, 400, 400, 56800, 0, 'UNKNOWN', 4, 180, NULL, NULL, NULL, NULL, NULL, 18, 25, 1798819199000, 'OPEN', '{"tuition":{"min":26000,"max":40000,"period":"YEAR","annualMax":40000},"accommodation":{"min":750,"max":8000,"period":"SEMESTER","annualMax":16000},"insuranceMax":400,"applicationFeeMax":400,"firstYearCostMax":56800,"costIncomplete":false,"cscaStatus":"UNKNOWN","hskLevelMin":4,"hskScoreMin":180,"ieltsMin":null,"toeflMin":null,"duolingoMin":null,"gpaMin":null,"gpaScale":null,"minAge":18,"maxAge":25,"deadlineDate":"2027-01-01T15:59:59.000Z","deadlineStatus":"OPEN","majors":["汉语言文学","汉语国际教育","网络与新媒体","英语","日语","金融科技","心理学","学前教育","美术学","设计学类","表演（影视戏剧）","音乐表演(声乐演唱)","音乐表演(器乐演奏)","音乐表演(音乐编创)","音乐表演(流行演唱)","舞蹈编导","播音与主持艺术","电子信息工程","电子科学与技术","计算机类","智慧交通","工程管理","智能建造","土木工程（国际工程创新班)","土木工程（数学力学创新班）","高分子材料与工程","材料科学与工程","化学","环境工程","新能源科学与工程","食品科学与工程","法学","行政管理","社会学","工商管理","电子商务","人力资源管理","市场营销","信息管理与信息系统"],"reviewReasons":["本科项目未明确 CSCA 要求"]}', '{"序号":"","院校分类":"","学校中文名":"深圳大学","学校英文名":"","所在城市":"深圳","项目类型":"UG","学费":"文科：26000元/年\\n理科：30000元/年\\n医学、艺术、体育类： 40000元/年","授课语言":"CHINESE","项目介绍":"深圳大学开设多门本科专业面向国际学生招生，覆盖文科、理科、医学、艺术等多个领域，专业选择丰富。学校依托大湾区区位优势，注重留学生培养管理与文化实践活动，拓展实习就业渠道，为国际学生提供优质的留学与发展平台。","学制":"4年","学制备注":"","专业列表":"汉语言文学\\n汉语国际教育\\n网络与新媒体\\n英语\\n日语\\n金融科技\\n心理学\\n学前教育\\n美术学\\n设计学类\\n表演（影视戏剧）\\n音乐表演(声乐演唱)\\n音乐表演(器乐演奏)\\n音乐表演(音乐编创)\\n音乐表演(流行演唱)\\n舞蹈编导\\n播音与主持艺术\\n电子信息工程\\n电子科学与技术\\n计算机类\\n智慧交通\\n工程管理\\n智能建造\\n土木工程（国际工程创新班)\\n土木工程（数学力学创新班）\\n高分子材料与工程\\n材料科学与工程\\n化学\\n环境工程\\n新能源科学与工程\\n食品科学与工程\\n法学\\n行政管理\\n社会学\\n工商管理\\n电子商务\\n人力资源管理\\n市场营销\\n信息管理与信息系统","专业方向":"汉语言文学专业大三分专业方向（商务、中文+AI）；\\n美术学专业大三分专业方向（国画、油画、版画、雕塑）；\\n设计学类大二分专业【艺术设计学（创意策划与设计管理）、视觉传达设计、环境设计、产品设计、服装与服饰设计、数字媒体艺术】。","申请要求及材料":"申请条件\\n（一）申请人须是非中国国籍公民，年满18周岁且不超过25周岁，持有效外国护照，身体健康，品行端正，遵守中国法律、法规和学校的规章制度。\\n（二）高中毕业及以上学历（申请时尚未毕业须提供预毕业证明，最迟在入学前取得高中毕业证书）。\\n（三）满足相应的语言水平要求（证书须在有效期内） 。\\n1、中文授课专业：\\n①理工科专业：HSK4级180分以上\\n②文科、医学、艺术专业：HSK5级180分以上\\n③汉语言文学、汉语国际教育本科：无HSK要求\\n*母语为汉语者经我校认定可免交相应语言水平证明。\\n（四）符合教育部教外函【2020】12号文件规定。\\n中华人民共和国教育部《教外函〔2020〕12号》。“一、依据《中华人民共和国国籍法》第五条，父母双方或一方为中国公民并定居在外国，本人出生时即具有外国国籍的，不具有中国国籍。自2021年起，其申请作为国际学生进入我高等学校本专科阶段学习，除符合学校的其他报名资格外，还应持有有效的外国护照或国籍证明文件4年（含）以上，且最近4年（截至入学年度的4月30日前）之内有在外国实际居住2年以上的记录（一年中实际在外国居住满9个月可按一年计算，以入境和出境签章为准）。二、祖国大陆（内地）、香港、澳门和台湾居民在移民并获得外国国籍后申请作为国际学生进入我高等学校本专科阶段学习的，应满足本通知第一项要求。”\\n\\n申请材料\\n（一）高中毕业证书、成绩单原件扫描件，应届生可提供就读高中出具的预毕业证明。（入学前必须取得毕业证书，入学时将查验）\\n（二）护照个人信息页\\n（三）护照照片\\n（四）语言水平证明 （证书须在有效期内）\\n中文授课专业（汉语言文学和汉语国际教育专业除外）：\\n①理工科专业：HSK4级证书（180分以上）\\n②文科、医学、艺术专业：HSK5级证书（180分以上）\\n（五）外国人体检报告\\n（六）个人履历（从小学至今）\\n（七）两封学校或任课老师推荐信（推荐人签字并注明电子邮箱和联系电话）和来华学习计划 (500字左右）。\\n","学期安排":"9月开学，每年两个学期","申请时间说明":"1月1日-3月20日（第一批）；\\n3月20日-5月31日（第二批）","奖学金类别":"广东省政府来粤留学生奖学金\\n深圳大运奖学金\\n荔园奖学金\\n国际中文教师奖学金","奖学金内容":"广东省政府来粤留学生奖学金，10000元/年\\n深圳大运奖学金，30000元/年\\n荔园奖学金：\\n一等，免学费，并提供 12000 元/年生活补助，按月发放\\n二等，免学费\\n三等，免学费的 50%\\n国际中文教师奖学金：学费、住宿费、生活费和综合医疗保险费","奖学金备注":"广东省政府来粤留学生奖学金：1.申请人须拥有外国国籍，持有有效外国护照，身体健康，对华友好。\\n2.申请来粤接受本科阶段学历教育的，须获得本人所在国高级中学（含）以上毕业证，年龄在30周岁以下；\\n3.申请人学业成绩优异，来粤学习目的明确，并根据拟就读大学的专业设置，并结合自身兴趣和专业特长，制订了清晰的学习计划。\\n4.申请人必须已被我校录取。\\n5.申请人必须是没有享受中国政府各类奖学金、孔子学院奖学金及其他任何中国各级政府资助形式。\\n\\n深圳大运奖学金：本科生最近两个学期每学期绩点不低于3.5且无必修不及格\\n\\n国际中文教师奖学金：具有高中学历，且中文水平考试成绩达到HSK（四级）210分、HSKK（中级）60分。","奖学金截止日期":"广东省政府来粤留学生奖学金、荔园奖学金：截止日期：5月31日\\n深圳大运奖学金：入学第二年开始申请（具体时间根据学院通知）\\n国际中文教师奖学金：2026年2月20日至2026年5月15日\\n","住宿费":"粤海校区宿舍设有单人间和双人间可供选择，费用为2400-8000元/学期；\\n丽湖校区宿舍为四人间，费用为750元/学期。\\n学生需按房型自行缴纳住宿费（水电费另外计收）。当前校内住宿紧张，有可能安排在校外住宿，具体费用另行通知。","保险费":"400元/学期","自费生申请费":"400元","奖学金申请费":"","费用备注":"","团体申请账号":"","奖学金发放形式\\noffer是否标明":"","是否可代收":"","截止日期":"","公司招生名额":"","学校招生计划":"","招生偏向":"","语言生是否面试、笔试":"","学历生是否面试、笔试":"","合作备注":"","特殊情况备注":"","学校申请更新频率":""}', '7d10beb3-407c-4b3b-9d8e-eb854095df98', 'NEEDS_REVIEW', 0, 0, 1782305253908, 1783443010770),
('d5f0d216-0603-4d22-908a-a866671a2404', NULL, 'e2a39eb1-9d45-43db-9fd1-7c714b250101', '深圳大学 · 本科 · 英文授课', 'UG', 'ENGLISH', NULL, '深圳大学开设全英文授课本科热门专业，涵盖工商管理、金融科技（微众东盟班）、国际经济与贸易三大优质方向。全程英文教学、采用国际原版教材，依托粤港澳大湾区区位优势与校企联合资源，接轨国际化课程体系与海外升学通道；兼顾商业管理、金融科技、跨境经贸热门赛道，配备专业师资与实践平台，助力国际学生拓宽全球视野、夯实专业能力，毕业后可直通名企就业与海外深造，是来华留学商科优选之选。', '4年', NULL, '工商管理\n金融科技（微众东盟班）\n国际经济与贸易', NULL, '申请条件\n（一）申请人须是非中国国籍公民，年满18周岁且不超过25周岁，持有效外国护照，身体健康，品行端正，遵守中国法律、法规和学校的规章制度。\n（二）高中毕业及以上学历（申请时尚未毕业须提供预毕业证明，最迟在入学前取得高中毕业证书）。\n（三）满足相应的语言水平要求（证书须在有效期内） 。\n英文授课专业：\n雅思5.5分/托福IBT80/多邻国100及以上。\n*母语为英语者经我校认定可免交相应语言水平证明。\n（四）符合教育部教外函【2020】12号文件规定。\n中华人民共和国教育部《教外函〔2020〕12号》。“一、依据《中华人民共和国国籍法》第五条，父母双方或一方为中国公民并定居在外国，本人出生时即具有外国国籍的，不具有中国国籍。自2021年起，其申请作为国际学生进入我高等学校本专科阶段学习，除符合学校的其他报名资格外，还应持有有效的外国护照或国籍证明文件4年（含）以上，且最近4年（截至入学年度的4月30日前）之内有在外国实际居住2年以上的记录（一年中实际在外国居住满9个月可按一年计算，以入境和出境签章为准）。二、祖国大陆（内地）、香港、澳门和台湾居民在移民并获得外国国籍后申请作为国际学生进入我高等学校本专科阶段学习的，应满足本通知第一项要求。”\n\n\n申请材料\n（一）高中毕业证书、成绩单原件扫描件，应届生可提供就读高中出具的预毕业证明。（入学前必须取得毕业证书，入学时将查验）\n（二）护照个人信息页\n（三）护照照片\n（四）语言水平证明 （证书须在有效期内）\n英文授课专业：雅思5.5分/托福IBT80/多邻国100及以上（英语母语者除外）\n（五）外国人体检报告\n（六）个人履历（从小学至今）\n（七）两封学校或任课老师推荐信（推荐人签字并注明电子邮箱和联系电话）和来华学习计划 (500字左右）。', '9月开学，每年两个学期', '1月1日-3月20日（第一批）；\n3月20日-5月31日（第二批）', '广东省政府来粤留学生奖学金\n深圳大运奖学金\n荔园奖学金', '广东省政府来粤留学生奖学金：10000元/年\n深圳大运奖学金：30000元/年\n荔园奖学金：\n一等，免学费，并提供 12000 元/年生活补助，按月发放\n二等，免学费\n三等，免学费的 50%', '广东省政府来粤留学生奖学金： 1.申请人须拥有外国国籍，持有有效外国护照，身体健康，对华友好。\n2.申请来粤接受本科阶段学历教育的，须获得本人所在国高级中学（含）以上毕业证，年龄在30周岁以下；\n3.申请人学业成绩优异，来粤学习目的明确，并根据拟就读大学的专业设置，并结合自身兴趣和专业特长，制订了清晰的学习计划。\n4.申请人必须已被我校录取。\n5.申请人必须是没有享受中国政府各类奖学金、孔子学院奖学金及其他任何中国各级政府资助形式。\n\n深圳大运奖学金：本科生最近两个学期每学期绩点不低于3.5且无必修不及格', '广东省政府来粤留学生奖学金、荔园奖学金：截止日期：5月31日\n深圳大运奖学金：入学第二年开始申请（具体时间根据学院通知）', '粤海校区宿舍设有单人间和双人间可供选择，费用为2400-8000元/学期；\n丽湖校区宿舍为四人间，费用为750元/学期。\n学生需按房型自行缴纳住宿费（水电费另外计收）。当前校内住宿紧张，有可能安排在校外住宿，具体费用另行通知。', '400元/学期', '400元', NULL, NULL, '文科：26000元/年', 26000, 26000, 'YEAR', 750, 8000, 400, 400, 42800, 0, 'UNKNOWN', NULL, NULL, 5.5, 80, 100, NULL, NULL, 18, 25, 1798819199000, 'OPEN', '{"tuition":{"min":26000,"max":26000,"period":"YEAR","annualMax":26000},"accommodation":{"min":750,"max":8000,"period":"SEMESTER","annualMax":16000},"insuranceMax":400,"applicationFeeMax":400,"firstYearCostMax":42800,"costIncomplete":false,"cscaStatus":"UNKNOWN","hskLevelMin":null,"hskScoreMin":null,"ieltsMin":5.5,"toeflMin":80,"duolingoMin":100,"gpaMin":null,"gpaScale":null,"minAge":18,"maxAge":25,"deadlineDate":"2027-01-01T15:59:59.000Z","deadlineStatus":"OPEN","majors":["工商管理","金融科技（微众东盟班）","国际经济与贸易"],"reviewReasons":["本科项目未明确 CSCA 要求"]}', '{"序号":"","院校分类":"","学校中文名":"深圳大学","学校英文名":"","所在城市":"深圳","项目类型":"UG","学费":"文科：26000元/年","授课语言":"ENGLISH","项目介绍":"深圳大学开设全英文授课本科热门专业，涵盖工商管理、金融科技（微众东盟班）、国际经济与贸易三大优质方向。全程英文教学、采用国际原版教材，依托粤港澳大湾区区位优势与校企联合资源，接轨国际化课程体系与海外升学通道；兼顾商业管理、金融科技、跨境经贸热门赛道，配备专业师资与实践平台，助力国际学生拓宽全球视野、夯实专业能力，毕业后可直通名企就业与海外深造，是来华留学商科优选之选。","学制":"4年","学制备注":"","专业列表":"工商管理\\n金融科技（微众东盟班）\\n国际经济与贸易","专业方向":"","申请要求及材料":"申请条件\\n（一）申请人须是非中国国籍公民，年满18周岁且不超过25周岁，持有效外国护照，身体健康，品行端正，遵守中国法律、法规和学校的规章制度。\\n（二）高中毕业及以上学历（申请时尚未毕业须提供预毕业证明，最迟在入学前取得高中毕业证书）。\\n（三）满足相应的语言水平要求（证书须在有效期内） 。\\n英文授课专业：\\n雅思5.5分/托福IBT80/多邻国100及以上。\\n*母语为英语者经我校认定可免交相应语言水平证明。\\n（四）符合教育部教外函【2020】12号文件规定。\\n中华人民共和国教育部《教外函〔2020〕12号》。“一、依据《中华人民共和国国籍法》第五条，父母双方或一方为中国公民并定居在外国，本人出生时即具有外国国籍的，不具有中国国籍。自2021年起，其申请作为国际学生进入我高等学校本专科阶段学习，除符合学校的其他报名资格外，还应持有有效的外国护照或国籍证明文件4年（含）以上，且最近4年（截至入学年度的4月30日前）之内有在外国实际居住2年以上的记录（一年中实际在外国居住满9个月可按一年计算，以入境和出境签章为准）。二、祖国大陆（内地）、香港、澳门和台湾居民在移民并获得外国国籍后申请作为国际学生进入我高等学校本专科阶段学习的，应满足本通知第一项要求。”\\n\\n\\n申请材料\\n（一）高中毕业证书、成绩单原件扫描件，应届生可提供就读高中出具的预毕业证明。（入学前必须取得毕业证书，入学时将查验）\\n（二）护照个人信息页\\n（三）护照照片\\n（四）语言水平证明 （证书须在有效期内）\\n英文授课专业：雅思5.5分/托福IBT80/多邻国100及以上（英语母语者除外）\\n（五）外国人体检报告\\n（六）个人履历（从小学至今）\\n（七）两封学校或任课老师推荐信（推荐人签字并注明电子邮箱和联系电话）和来华学习计划 (500字左右）。\\n","学期安排":"9月开学，每年两个学期","申请时间说明":"1月1日-3月20日（第一批）；\\n3月20日-5月31日（第二批）","奖学金类别":"广东省政府来粤留学生奖学金\\n深圳大运奖学金\\n荔园奖学金","奖学金内容":"广东省政府来粤留学生奖学金：10000元/年\\n深圳大运奖学金：30000元/年\\n荔园奖学金：\\n一等，免学费，并提供 12000 元/年生活补助，按月发放\\n二等，免学费\\n三等，免学费的 50%","奖学金备注":"广东省政府来粤留学生奖学金： 1.申请人须拥有外国国籍，持有有效外国护照，身体健康，对华友好。\\n2.申请来粤接受本科阶段学历教育的，须获得本人所在国高级中学（含）以上毕业证，年龄在30周岁以下；\\n3.申请人学业成绩优异，来粤学习目的明确，并根据拟就读大学的专业设置，并结合自身兴趣和专业特长，制订了清晰的学习计划。\\n4.申请人必须已被我校录取。\\n5.申请人必须是没有享受中国政府各类奖学金、孔子学院奖学金及其他任何中国各级政府资助形式。\\n\\n深圳大运奖学金：本科生最近两个学期每学期绩点不低于3.5且无必修不及格","奖学金截止日期":"广东省政府来粤留学生奖学金、荔园奖学金：截止日期：5月31日\\n深圳大运奖学金：入学第二年开始申请（具体时间根据学院通知）\\n","住宿费":"粤海校区宿舍设有单人间和双人间可供选择，费用为2400-8000元/学期；\\n丽湖校区宿舍为四人间，费用为750元/学期。\\n学生需按房型自行缴纳住宿费（水电费另外计收）。当前校内住宿紧张，有可能安排在校外住宿，具体费用另行通知。","保险费":"400元/学期","自费生申请费":"400元","奖学金申请费":"","费用备注":"","团体申请账号":"","奖学金发放形式\\noffer是否标明":"","是否可代收":"","截止日期":"","公司招生名额":"","学校招生计划":"","招生偏向":"","语言生是否面试、笔试":"","学历生是否面试、笔试":"","合作备注":"","特殊情况备注":"","学校申请更新频率":""}', '7d10beb3-407c-4b3b-9d8e-eb854095df98', 'NEEDS_REVIEW', 0, 0, 1782305253911, 1783443010774),
('04e747b9-ba9c-4116-9876-0e503065ba21', NULL, 'e2a39eb1-9d45-43db-9fd1-7c714b250101', '深圳大学 · 硕士 · 中文授课', 'MASTER', 'CHINESE', NULL, '深圳大学来华硕士研究生教育办学资质正规、培养体系完善，拥有国家级来华留学质量认证资质，招生专业包含文科、理科、艺术等多个领域，项目依托深圳大学优质学科实力与大湾区产业资源，采用中文授课、全日制培养模式，设置清晰的人才培养方案，兼顾理论教学与实践创新。学校配备专业教学与管理团队，提供完善的留学服务、校园文化活动及实习就业渠道，语言门槛友好，是国际学生攻读中文授课硕士、提升专业能力与综合素养的优质选择。', '2-3年', NULL, '国际中文教育\n新闻与传播\n心理学\n应用心理\n外国语言文学\n艺术学\n设计学\n设计\n控制科学与工程\n控制工程\n计算机技术\n建筑学\n建筑\n人工智能（土木）\n材料科学与工程\n材料工程\n环境工程\n法学\n法律（法学）\n法律（非法学）\n公共管理学', NULL, '申请条件\n（一）申请人须是非中国国籍公民，持有效外国护照，身体健康，品行端正，遵守中国法律、法规和学校的规章制度。\n（二）申请人必须具有大学本科毕业以上学历（申请时尚未毕业须提供预毕业证明，最迟在入学前取得大学本科毕业证书）。年龄一般在35周岁以下。\n（三）满足相应的语言水平要求（证书须在有效期内） 。\n中文授课专业\n①理工科专业：HSK4级180分以上\n②文科、医学、艺术专业：HSK5级180分以上\n* 母语为汉语者经我校认定可免交相应语言水平证明。\n\n申请材料\n（一）本科毕业证书、学位证书。应届毕业生可提供就读大学出具的预毕业证明（入学前必须取得毕业证书，入学时将查验）。\n（二）本科阶段全部课程的成绩单\n（三）两封推荐信（教授或副教授出具，中文/英文书写，须有推荐人姓名和联系方式）\n（四）一份个人陈述（800字左右，用英文或中文撰写，内容应包括个人学习经历、学习计划等）\n（五）护照个人信息页\n（六）护照照片\n（七）语言水平证明\n中文授课专业\n①理工科专业：HSK4级证书（180分以上）\n②文科、医学、艺术专业：HSK5级证书（180分以上）\n* 母语为汉语者经我校认定可免交相应语言水平证明。\n（八）外国人体检报告\n（九）个人履历（从小学至今）\n（十）申请广东省政府来粤留学生奖学金者请下载《广东省政府来粤留学生奖学金申请表》填写完整后再上传。', '9月开学，每年两个学期', '1月1日-5月31日', '广东省政府来粤留学生奖学金\n深圳大运奖学金\n荔园奖学金\n国际中文教师奖学金', '广东省政府来粤留学生奖学金：20000元/年\n深圳大运奖学金：35000元/年\n荔园奖学金：\n一等，免学费，并提供 12000元/年生活补助，按月发放\n二等，免学费\n三等，免学费的 50%\n国际中文教师奖学金：学费、住宿费、生活费和综合医疗保险费', '广东省政府来粤留学生奖学金：1.申请人须拥有外国国籍，持有有效外国护照，身体健康，对华友好。\n2.申请来粤接受硕士研究生阶段学历教育的，须具有学士学位或相当学历，年龄在35周岁以下；\n3.申请人学业成绩优异，来粤学习目的明确，并根据拟就读大学的专业设置，并结合自身兴趣和专业特长，制订了清晰的学习计划。\n4.申请人必须已被我校录取。\n5.申请人必须是没有享受中国政府各类奖学金、孔子学院奖学金及其他任何中国各级政府资助形式。\n\n深圳大运奖学金：硕士生最近两个学期每学期绩点不低于3.0且无必修不及格\n\n国际中文教师奖学金：具有高中学历，且中文水平考试成绩达到HSK（四级）210分、HSKK（中级）60分。', '广东省政府来粤留学生奖学金、荔园奖学金：截止日期：5月31日\n深圳大运奖学金：入学第二年开始申请（具体时间根据学院通知）\n国际中文教师奖学金：2026年2月20日至2026年5月15日', '粤海校区宿舍设有单人间和双人间可供选择，费用为2400-8000元/人/学期；丽湖校区宿舍为四人间，费用为750元人/学期。学生需按房型自行缴纳住宿费（水电费另外计收）。当前校内住宿紧张，有可能安排在校外住宿，具体费用另行通知。', '400元/学期', '400元', NULL, NULL, '文科：30000元/年\n理科：35000元/年\n艺术类： 45000元/年', 30000, 45000, 'YEAR', 750, 8000, 400, 400, 61800, 0, 'NOT_REQUIRED', 4, 180, NULL,