INSERT INTO `programs` (`id`, `external_id`, `school_id`, `name`, `program_type`, `teaching_language`, `tags`, `introduction`, `duration`, `duration_note`, `major_text`, `direction_text`, `requirements_text`, `semester_text`, `application_time_text`, `scholarship_category`, `scholarship_content`, `scholarship_note`, `scholarship_deadline_text`, `accommodation_text`, `insurance_text`, `application_fee_text`, `scholarship_application_fee_text`, `fee_note`, `tuition_text`, `tuition_min`, `tuition_max`, `tuition_period`, `accommodation_min`, `accommodation_max`, `insurance_max`, `application_fee_max`, `first_year_cost_max`, `cost_incomplete`, `csca_status`, `hsk_level_min`, `hsk_score_min`, `ielts_min`, `toefl_min`, `duolingo_min`, `gpa_min`, `gpa_scale`, `min_age`, `max_age`, `deadline_date`, `deadline_status`, `parsed_json`, `raw_json`, `source_batch_id`, `review_status`, `manually_verified`, `archived`, `created_at`, `updated_at`) VALUES
('d130c9a2-7945-4984-b3e5-dec7c59034fe', NULL, '57e95657-383f-4d38-8c5c-3ed496a4dcad', '嘉兴大学 · 本科 · 中文授课', 'UG', 'CHINESE', NULL, '嘉兴大学本科项目提供多个专业的本科教育。', '4-5年', '临床医学\n（这个专业为5年制，其余专业为4年制）', '工商管理\n纺织工程\n土木工程\n汉语国际教育\n机械设计制造及其自动化\n计算机科学与技术\n护理学\n药学\n工业设计\n服装设计与工程\n日语\n临床医学\n环境设计\n视觉传达设计\n数字媒体艺术', NULL, '申请要求：\n1.非中国籍公民，持有外国有效护照，原则上年龄在18-30周岁之间，具有高中毕业证书或证明（申请时尚未毕业者须提供预毕业证明，最迟须在入学前取得高中毕业证书），成绩优良。申请者身心健康，品行端正，无犯罪记录，保证留学期间遵守中国法律法规和校纪校规，尊重中国文化习俗。\n2.符合教育部教外函〔2020〕12号文件规定：\n（1）父母双方或一方为中国公民并定居在外国，本人出生时即具有外国国籍的，不具有中国国籍。自2021年起，其申请作为国际学生进入我高等学校本专科阶段学习，除符合学校的其他报名资格外，还应持有有效的外国护照或国籍证明文件4年（含）以上，且最近4年（截至入学年度的4月30日前）之内有在外国实际居住2年以上的记录（一年中实际在外国居住满9个月可按一年计算，以入境和出境签章为准）。\n（2）祖国大陆（内地）、香港、澳门和台湾居民在移民并获得外国国籍后申请作为国际学生进入我高等学校本专科阶段学习的，应满足第（1）项要求。\n3.申请人具有外国国籍的同时是否具有中华人民共和国国籍，以中国公安机关出入境管理部门的国籍认定结论为准。如在申请、录取及入学后被认定具有中国国籍的，将被取消申请、录取或学习资格。\n4. 符合以下语言水平要求：\n申请中文授课本科项目的国际学生，需持HSK4级（180分及以上）成绩单或持相关满足学校条件要求的证明。\n申请材料：\n1.有效期内的护照首页；\n2.高中毕业证书或证明、高中成绩单（应届高中毕业生由本人所在学校出具预毕业证明，报到入学核验前补交高中毕业证书；申请汉语语言项目的国际学生提供最高学历证书或证明、成绩单）；\n3.无犯罪记录证明；\n4.外国人体格检查表；注：申请人应严格按照《外国人体格检查表》中要求的项目进行检查，检查内容必须包括表中所列的所有项目。缺项、未贴有本人照片或照片上未盖医院印章、无医师签字、无医院盖章的表格无效。体检结果原则上六个月内有效）；\n5.个人陈述（800字以内，内容须包含个人学习工作经历、申请理由、学习计划和个人优势等）；\n6.已在中国境内者还需提供本次入境的有效签证或者居留许可；\n7.已在中国其他高校就读的申请者需提供由原所在学校出具的学习证明和成绩单；\n8.转学证明（转学的申请者需提供）；\n9.毕业学校教师推荐信1封（推荐人签字并附联系电话和邮箱地址）；\n10.语言成绩证明；\n11.近三个月的护照照片（照片参照格式：35mm * 45mm，免冠证件照，白色背景无边框，头部占照片尺寸的2/3，照片尺寸不低于320*240像素，高宽比为4:3，大小为100-500KB，JPG格式）；\n12.3分钟内自我介绍视频；\n13.学校可能要求申请者提供的其他补充、补正材料。\n上述申请材料原件若非中文或英文，须提供中文或英文翻译件（加盖翻译公司印章），其中毕业证书或证明、成绩单的中文或英文翻译件须经公证。学校可根据实际情况对申请人进行视频面试。', NULL, '2026年秋季入学申请时间：\n2026年3月9日-2026年6月30日', '1.浙江省政府来华留学生奖学金\n2.嘉兴大学国际学生奖学金', '嘉兴大学国际学生奖学金设置情况：\n1.学历生新生奖学金\n2.优秀学历生奖学金\n3.优秀汉语进修生奖学金\n4.国际学生友好奖学金\n5.华友钴业企业奖学金（面向印度尼西亚和匈牙利国籍申请者）', NULL, '没有明确的截止日期，\n专业录满即截止', '3600元/学年', '1000元/学年', '400元\n（报名费）', NULL, '体检费：约700元/人\n书本费：根据书本实际定价\n居留许可证:申请居留期限1年以内约500/人 一年约800/人', '16000元/学年-21000元/学年', 16000, 21000, 'UNKNOWN', 3600, 3600, 1000, 400, 26000, 0, 'UNKNOWN', 4, NULL, NULL, NULL, NULL, NULL, NULL, 18, 